            runner="$RUNNER_BUG"
          else
            runner="$RUNNER_STORY"
          fi
        fi
        if [ -n "$runner" ]; then
          echo "run=true" >> "$GITHUB_OUTPUT"
          echo "runner=$runner" >> "$GITHUB_OUTPUT"
