suite('smAgent: fork PR dispatch (gh-1075)', function () {

    var BASE = 'epam/dmtools-dart';
    var FORK = 'yuryby/dmtools-dart';
    var BRANCH = 'fix/android-dap-home-sandbox';
    var NO_REF_ERR = '422: No ref found for: ' + BRANCH;
