        assert.deepEqual(lint.extractTriggers('on: [push, workflow_dispatch]\njobs: {}'),
            ['push', 'workflow_dispatch']);
    });

    test('on: block ends at the next top-level key — jobs content is ignored', function () {
        var yml = [
            'on:',
            '  schedule:',
