        }
        if (branchLegGuardModule.hasActiveLegRunOnBranch(runs, branch, {
                workflowFile: workflowFile,
                staleNonRunningMs: STALE_NON_RUNNING_WORKFLOW_MS,
                nowMs: Date.now()
            })) {
            return true;
        }
    }
