### Thread 8 — probe target repo

Edit `forkPullRefLive` in smAgent.js:

```javascript
function forkPullRefLive(repoInfo, prNumber) {
   var ref = forkDispatchModule.pullHeadRef(prNumber);
   // gh-1075 review (round 2, BLOCKING): the SM's cwd is the ENGINE
   // checkout — `origin` there names the engine repo, never the
   // dispatch target (js/smAgent.js gh-1070 silent-update comment,
   // live-verified: the reconcile job's working directory is the
   // dmtools-agents engine checkout; the builder clones the TARGET
   // repo instead). Probing `origin` would ask the ENGINE repo about
   // refs/pull/<N>/head and park LIVE fork heads on every non-self-host
   // SM (AC2 inverted). Probe the TARGET repo named by repoInfo,
   // authenticated, with the established split-literal token URL
   // (validationLiveness.forkPushTokenUrl): '${GH_TOKEN}' interpolates
   // in the child env exactly like the silent-update commands, so the
   // secret never appears in source or the captured command string.
   var full = String(repoInfo.owner || '') + '/' + String(repoInfo.repo || '');
   var targetUrl = validationLivenessModule.forkPushTokenUrl(full);
   try {
       var out = cli_execute_command({
           command: 'git ls-remote ' + targetUrl + ' + ref
       });
       return String(out || '').indexOf(ref) !== -1;
   } catch (eProbe) {
       console.warn(' ⚠️ fork pull-ref probe DEGRADED for pr-' + prNumber +
           ' (ls-remote ' + full + ' failed: ' + (eProbe.message || eProbe) +
           ') — treating the head as LIVE (fail-open, gh-1075)');
       return true;
