        if (idx === -1) break;
        var next = s.charAt(idx + token.length);
        var prev = idx > 0 ? s.charAt(idx - 1) : '';
        if (!isDigitOrDash(next) && !isWordChar(prev)) return true;
        from = idx + 1;
    }
    return false;
}
