+    } catch (eProbe) {
+        console.warn('  ⚠️  fork pull-ref probe DEGRADED for ' + ref +
+            ' (' + full + ' probe failed: ' + (eProbe.message || eProbe) +
+            ') — treating the head as LIVE (fail-open, gh-1075)');
+        return true;
+    }
