    var LEG_RULE = { source: 'github', id: 'review-on-label-gh1075',
        query: { type: 'pr', labels: ['agent:review'], draft: false },
        inputs: { pr: '{prNumber}', leg: 'review' },
        workflowRef: '{branch}', limit: 1 };

