function isDigitOrDash(ch) {
   return (ch >= '0' && ch <= '9') || ch === '-';
}

function isWordChar(ch) {
   return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
       (ch >= '0' && ch <= '9') || ch === '-' || ch === '#';
}

function titleHasPrToken(title, prNumber) {
