        }).map(function (c) { return String(c.body); });
    }

    // The ls-remote probe mock: fetchable pull ref by default.
    function probeCli(fetchable) {
        return function (cmdOpts) {
            if (cmdOpts.command.indexOf('ls-remote') !== -1) {
