```javascript
// Whole-token boundary predicates (gh-1075 review — CRAP ratchet): the
// loop below used to inline both tests; named helpers keep the loop's
// cyclomatic load at one branch per iteration. A trailing key char
// (digit/'-') rejects ('pr-1591' never matches 'pr-15910'); a letter/
// digit/'-'/'#' prefix rejects ('pr-1591' never matches 'gh-pr-1591-x'
// or '#pr-1591') — boundary rules mirror smAgent.stubAnchorMatches.
function isDigitOrDash(ch) {
   return (ch >= '0' && ch <= '9') || ch === '-';
}

function isWordChar(ch) {
   return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
       (ch >= '0' && ch <= '9') || ch === '-' || ch === '#';
}

function titleHasPrToken(title, prNumber) {
   var s = String(title || '');
   var token = '[REDACTED:Sensitive Value]' + prNumber;
   var from = 0;
   while (from <= s.length - token.length) {
       var idx = s.indexOf(token, from);
       if (idx === -1) break;
       var next = s.charAt(idx + token.length);
       var prev = idx > 0 ? s.charAt(idx - 1) : '';
       if (!isDigitOrDash(next) && !isWordChar(prev)) return true;
       from = idx + 1;
   }
   return false;
}
```

Complexity of titleHasPrToken now: while + if + (|| in while cond) ≈ cyclomatic 4. CRAP with full branch coverage: low. The helpers each ~2-3. Good.

